from collections import deque

class Solution:
    def allPathsSourceTarget(self, graph: list[list[int]]) -> list[list[int]]:
        queue, result = deque([[0]]), []
        while queue:
            path = queue.popleft()
            if path[-1] == len(graph) - 1:
                result.append(path)
            else:
                for neighbor in graph[path[-1]]:
                    queue.append(path + [neighbor])
        return result
